contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 seed) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= seed, "insufficient test balance");
        uint256 cBalBefore = address(c).balance;
        uint256 ownerBalBefore = address(this).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        uint256 ownerBalAfter = address(this).balance;
        uint256 cBalAfter = address(c).balance;
        assert(ownerBalAfter == ownerBalBefore + cBalBefore && cBalAfter == 0);
    }

    receive() external payable {}
}

