// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 seed) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= seed);
        uint256 cBalBefore = address(c).balance;
        uint256 ownerBalBefore = address(this).balance;
        try c.withdrawAll() {} catch { return; }
        uint256 ownerBalAfter = address(this).balance;
        uint256 cBalAfter = address(c).balance;
        assertTrue(ownerBalAfter == ownerBalBefore + cBalBefore && cBalAfter == 0);
    }

    function testFuzz_run(uint256 seed) public {
        _run(seed);
    }

    receive() external payable {}
}
